#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H, N;
    cin >> W >> H >> N;

    int sx, sy, gx, gy;
    cin >> sx >> sy >> gx >> gy;

    vector<tuple<int, int, int, int>> walls(N);
    for (int i = 0; i < N; i++) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        walls[i] = {x1, y1, x2, y2};
    }

    // We will build a graph where nodes are points (including start, goal, and wall endpoints)
    // and edges represent ability to move directly without crossing walls.
    // Then run BFS/0-1 BFS on number of walls crossed.

    // Collect all important points: start, goal, and all wall endpoints
    vector<pair<int, int>> points;
    points.emplace_back(sx, sy);
    points.emplace_back(gx, gy);
    for (auto [x1, y1, x2, y2] : walls) {
        points.emplace_back(x1, y1);
        points.emplace_back(x2, y2);
    }

    // Remove duplicates
    sort(points.begin(), points.end());
    points.erase(unique(points.begin(), points.end()), points.end());
    int P = points.size();

    // Map point to index
    map<pair<int, int>, int> idx;
    for (int i = 0; i < P; i++) idx[points[i]] = i;

    int start_idx = idx[{sx, sy}];
    int goal_idx = idx[{gx, gy}];

    // Build adjacency: for each pair of points, check if we can move directly without crossing any wall
    // Since N <= 100 and P <= 202, O(P^2 * N) is fine.
    const int INF = 1e9;
    vector<vector<int>> dist(P, vector<int>(P, INF));
    for (int i = 0; i < P; i++) {
        for (int j = i+1; j < P; j++) {
            auto [x1, y1] = points[i];
            auto [x2, y2] = points[j];
            // Movement must be axis-aligned? Actually problem says move freely within area, so we consider straight line.
            // But walls are axis-aligned, crossing count is number of walls intersected.
            // We'll compute number of walls crossed on segment (x1,y1)-(x2,y2)
            int crosses = 0;
            bool blocked = false;
            for (auto [wx1, wy1, wx2, wy2] : walls) {
                // Determine if segment intersects wall (excluding endpoints touching)
                // Wall is axis-aligned segment.
                auto intersect = [&](int ax, int ay, int bx, int by, int cx, int cy, int dx, int dy) -> bool {
                    // Check if segment AB intersects segment CD (including endpoints? We exclude touching at endpoints)
                    // Using orientation method
                    auto orient = [](int px, int py, int qx, int qy, int rx, int ry) -> long long {
                        return (long long)(qx - px) * (ry - py) - (long long)(qy - py) * (rx - px);
                    };
                    auto onSegment = [](int px, int py, int qx, int qy, int rx, int ry) -> bool {
                        return min(px, qx) <= rx && rx <= max(px, qx) &&
                               min(py, qy) <= ry && ry <= max(py, qy);
                    };
                    long long o1 = orient(ax, ay, bx, by, cx, cy);
                    long long o2 = orient(ax, ay, bx, by, dx, dy);
                    long long o3 = orient(cx, cy, dx, dy, ax, ay);
                    long long o4 = orient(cx, cy, dx, dy, bx, by);
                    if (o1 == 0 && onSegment(ax, ay, bx, by, cx, cy)) return true;
                    if (o2 == 0 && onSegment(ax, ay, bx, by, dx, dy)) return true;
                    if (o3 == 0 && onSegment(cx, cy, dx, dy, ax, ay)) return true;
                    if (o4 == 0 && onSegment(cx, cy, dx, dy, bx, by)) return true;
                    return (o1 > 0) != (o2 > 0) && (o3 > 0) != (o4 > 0);
                };
                if (intersect(x1, y1, x2, y2, wx1, wy1, wx2, wy2)) {
                    // Check if intersection is at endpoints of movement segment
                    // If the intersection point is exactly x1,y1 or x2,y2, we don't count as crossing? 
                    // Problem says crossing at intersection of walls is not allowed, but crossing at endpoints of movement?
                    // Actually moving from point to point: if the path touches a wall endpoint, it's ambiguous.
                    // We'll treat touching at start or end as not crossing.
                    bool touchStart = (x1 == wx1 && y1 == wy1) || (x1 == wx2 && y1 == wy2);
                    bool touchEnd = (x2 == wx1 && y2 == wy1) || (x2 == wx2 && y2 == wy2);
                    if (!touchStart && !touchEnd) {
                        crosses++;
                    }
                }
            }
            if (crosses < INF) {
                dist[i][j] = dist[j][i] = crosses;
            }
        }
    }

    // Now we need shortest path from start to goal minimizing total crosses.
    // Since edge weight is number of walls crossed (non-negative), we can use Dijkstra.
    // P <= 202, so O(P^2) Dijkstra is fine.
    vector<int> d(P, INF);
    vector<bool> used(P, false);
    d[start_idx] = 0;
    for (int iter = 0; iter < P; iter++) {
        int v = -1;
        for (int u = 0; u < P; u++) {
            if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
        }
        if (v == -1 || d[v] == INF) break;
        used[v] = true;
        for (int u = 0; u < P; u++) {
            if (dist[v][u] < INF && d[v] + dist[v][u] < d[u]) {
                d[u] = d[v] + dist[v][u];
            }
        }
    }

    cout << d[goal_idx] << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int W, H;
    while(cin >> W >> H && (W||H)) {
        int N; cin >> N;
        vector<int> x1v(N),y1v(N),x2v(N),y2v(N);
        vector<int> xs={0,W}, ys={0,H};
        int sx,sy,ex,ey;
        cin>>sx>>sy>>ex>>ey;
        xs.push_back(sx); ys.push_back(sy);
        xs.push_back(ex); ys.push_back(ey);
        for(int i=0;i<N;i++){
            cin>>x1v[i]>>y1v[i]>>x2v[i]>>y2v[i];
            xs.push_back(x1v[i]); xs.push_back(x2v[i]);
            ys.push_back(y1v[i]); ys.push_back(y2v[i]);
        }
        sort(xs.begin(),xs.end()); xs.erase(unique(xs.begin(),xs.end()),xs.end());
        sort(ys.begin(),ys.end()); ys.erase(unique(ys.begin(),ys.end()),ys.end());
        int R=xs.size()-1, C=ys.size()-1;
        // cell (i,j): x in [xs[i],xs[i+1]], y in [ys[j],ys[j+1]]
        // Check wall between cell (i,j) and (i+1,j): vertical line x=xs[i+1], y in [ys[j],ys[j+1]]
        auto hasWallV=[&](int xi, int yj)->bool{
            double cx=xs[xi], ylo=ys[yj], yhi=ys[yj+1];
            for(int k=0;k<N;k++){
                if(x1v[k]==x2v[k] && x1v[k]==cx){
                    double wlo=min(y1v[k],y2v[k]), whi=max(y1v[k],y2v[k]);
                    if(wlo<=ylo && yhi<=whi) return true;
                }
            }
            return false;
        };
        auto hasWallH=[&](int xi, int yj)->bool{
            double cy=ys[yj], xlo=xs[xi], xhi=xs[xi+1];
            for(int k=0;k<N;k++){
                if(y1v[k]==y2v[k] && y1v[k]==cy){
                    double wlo=min(x1v[k],x2v[k]), whi=max(x1v[k],x2v[k]);
                    if(wlo<=xlo && xhi<=whi) return true;
                }
            }
            return false;
        };
        int si=lower_bound(xs.begin(),xs.end(),sx)-xs.begin();
        // start is a point, find cell: xs[si-1]..xs[si]
        si--;
        int sj=lower_bound(ys.begin(),ys.end(),sy)-ys.begin(); sj--;
        int ei=lower_bound(xs.begin(),xs.end(),ex)-xs.begin(); ei--;
        int ej=lower_bound(ys.begin(),ys.end(),ey)-ys.begin(); ej--;
        vector<vector<int>> dist(R,vector<int>(C,1e9));
        deque<pair<int,int>> dq;
        dist[si][sj]=0; dq.push_back({si,sj});
        int dx[]={1,-1,0,0}, dy[]={0,0,1,-1};
        while(!dq.empty()){
            auto [x,y]=dq.front(); dq.pop_front();
            for(int d=0;d<4;d++){
                int nx=x+dx[d], ny=y+dy[d];
                if(nx<0||nx>=R||ny<0||ny>=C) continue;
                int w=0;
                if(d==0) w=hasWallV(x+1,y)?1:0;
                else if(d==1) w=hasWallV(x,y)?1:0;
                else if(d==2) w=hasWallH(x,y+1)?1:0;
                else w=hasWallH(x,y)?1:0;
                if(dist[x][y]+w<dist[nx][ny]){
                    dist[nx][ny]=dist[x][y]+w;
                    if(w==0) dq.push_front({nx,ny});
                    else dq.push_back({nx,ny});
                }
            }
        }
        cout<<dist[ei][ej]<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

/*
We compress coordinates using all x/y values that matter:
- 0 and W / 0 and H (outer boundary)
- start/end coordinates
- every wall endpoint coordinate
Then we build cells between consecutive compressed x/y coordinates.
Moving between adjacent cells is free unless their shared side is occupied by a wall segment,
in which case cost = 1 (crossing one wall).

Important:
- Walls are axis-aligned segments of zero width.
- Crossing at wall intersections is forbidden, but with cell-based movement this is naturally avoided:
  crossings happen through interiors of cell sides, never exactly at compressed grid vertices.
- Moving on walls/boundary is also avoided since states are cell interiors.
*/

struct Edge01 {
    int to, w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H, N;
    cin >> W >> H >> N;
    int sx, sy, tx, ty;
    cin >> sx >> sy >> tx >> ty;

    struct Wall {
        int x1, y1, x2, y2;
    };
    vector<Wall> walls(N);

    vector<int> xs{0, W, sx, tx};
    vector<int> ys{0, H, sy, ty};

    for (int i = 0; i < N; ++i) {
        cin >> walls[i].x1 >> walls[i].y1 >> walls[i].x2 >> walls[i].y2;
        xs.push_back(walls[i].x1);
        xs.push_back(walls[i].x2);
        ys.push_back(walls[i].y1);
        ys.push_back(walls[i].y2);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    int X = (int)xs.size();
    int Y = (int)ys.size();

    // blockR[ix][iy]: boundary between cell (ix-1,iy) and (ix,iy), i.e. vertical side x = xs[ix]
    // valid for ix = 1..X-2, iy = 0..Y-2
    vector<vector<int>> blockR(X, vector<int>(Y, 0));

    // blockU[ix][iy]: boundary between cell (ix,iy-1) and (ix,iy), i.e. horizontal side y = ys[iy]
    // valid for iy = 1..Y-2, ix = 0..X-2
    vector<vector<int>> blockU(X, vector<int>(Y, 0));

    auto xid = [&](int x) {
        return (int)(lower_bound(xs.begin(), xs.end(), x) - xs.begin());
    };
    auto yid = [&](int y) {
        return (int)(lower_bound(ys.begin(), ys.end(), y) - ys.begin());
    };

    for (auto &w : walls) {
        if (w.x1 == w.x2) {
            // vertical wall at x = x1, from y1 to y2
            int xi = xid(w.x1);
            int y1 = yid(min(w.y1, w.y2));
            int y2 = yid(max(w.y1, w.y2));
            for (int yi = y1; yi < y2; ++yi) {
                blockR[xi][yi] = 1;
            }
        } else {
            // horizontal wall at y = y1, from x1 to x2
            int yi = yid(w.y1);
            int x1 = xid(min(w.x1, w.x2));
            int x2 = xid(max(w.x1, w.x2));
            for (int xi = x1; xi < x2; ++xi) {
                blockU[xi][yi] = 1;
            }
        }
    }

    int CW = X - 1, CH = Y - 1; // number of cells in x/y

    auto cell_id = [&](int cx, int cy) {
        return cy * CW + cx;
    };

    int scx = (int)(upper_bound(xs.begin(), xs.end(), sx) - xs.begin()) - 1;
    int scy = (int)(upper_bound(ys.begin(), ys.end(), sy) - ys.begin()) - 1;
    int tcx = (int)(upper_bound(xs.begin(), xs.end(), tx) - xs.begin()) - 1;
    int tcy = (int)(upper_bound(ys.begin(), ys.end(), ty) - ys.begin()) - 1;

    const int INF = 1e9;
    deque<int> dq;
    vector<int> dist(CW * CH, INF);

    int s = cell_id(scx, scy);
    int t = cell_id(tcx, tcy);

    dist[s] = 0;
    dq.push_back(s);

    while (!dq.empty()) {
        int v = dq.front();
        dq.pop_front();
        int cx = v % CW;
        int cy = v / CW;
        int d = dist[v];

        // left
        if (cx > 0) {
            int w = blockR[cx][cy];
            int to = cell_id(cx - 1, cy);
            if (dist[to] > d + w) {
                dist[to] = d + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
        // right
        if (cx + 1 < CW) {
            int w = blockR[cx + 1][cy];
            int to = cell_id(cx + 1, cy);
            if (dist[to] > d + w) {
                dist[to] = d + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
        // down
        if (cy > 0) {
            int w = blockU[cx][cy];
            int to = cell_id(cx, cy - 1);
            if (dist[to] > d + w) {
                dist[to] = d + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
        // up
        if (cy + 1 < CH) {
            int w = blockU[cx][cy + 1];
            int to = cell_id(cx, cy + 1);
            if (dist[to] > d + w) {
                dist[to] = d + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
    }

    cout << dist[t] << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MAX = 1002; // coordinate compression size
    static int[] parent;
    static int[] rank;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int W = Integer.parseInt(st.nextToken());
        int H = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(br.readLine());

        // Store walls: x1, y1, x2, y2 (x1 <= x2, y1 <= y2)
        int[][] walls = new int[N][4];
        List<Integer> xs = new ArrayList<>();
        List<Integer> ys = new ArrayList<>();
        xs.add(0); xs.add(W);
        ys.add(0); ys.add(H);

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            int d = Integer.parseInt(st.nextToken());
            // Normalize: ensure x1 <= x2, y1 <= y2
            if (a > c) { int tmp = a; a = c; c = tmp; }
            if (b > d) { int tmp = b; b = d; d = tmp; }
            walls[i][0] = a;
            walls[i][1] = b;
            walls[i][2] = c;
            walls[i][3] = d;
            xs.add(a); xs.add(c);
            ys.add(b); ys.add(d);
        }

        st = new StringTokenizer(br.readLine());
        int sx = Integer.parseInt(st.nextToken());
        int sy = Integer.parseInt(st.nextToken());
        int tx = Integer.parseInt(st.nextToken());
        int ty = Integer.parseInt(st.nextToken());
        xs.add(sx); xs.add(tx);
        ys.add(sy); ys.add(ty);

        // Coordinate compression
        Collections.sort(xs);
        Collections.sort(ys);
        // Remove duplicates
        xs = new ArrayList<>(new LinkedHashSet<>(xs));
        ys = new ArrayList<>(new LinkedHashSet<>(ys));

        int xSize = xs.size();
        int ySize = ys.size();

        // Map original coordinates to compressed indices
        Map<Integer, Integer> xMap = new HashMap<>();
        Map<Integer, Integer> yMap = new HashMap<>();
        for (int i = 0; i < xSize; i++) xMap.put(xs.get(i), i);
        for (int i = 0; i < ySize; i++) yMap.put(ys.get(i), i);

        // Build grid: cell[i][j] corresponds to rectangle between xs[i]..xs[i+1] and ys[j]..ys[j+1]
        // We'll treat walls as edges between adjacent cells.
        // We'll have (xSize-1) * (ySize-1) cells.
        int cellsX = xSize - 1;
        int cellsY = ySize - 1;
        int totalCells = cellsX * cellsY;
        parent = new int[totalCells];
        rank = new int[totalCells];
        for (int i = 0; i < totalCells; i++) {
            parent[i] = i;
            rank[i] = 0;
        }

        // Mark cells that contain start and end points
        int startCell = -1, endCell = -1;
        for (int i = 0; i < cellsX; i++) {
            for (int j = 0; j < cellsY; j++) {
                if (xs.get(i) <= sx && sx <= xs.get(i+1) && ys.get(j) <= sy && sy <= ys.get(j+1)) {
                    startCell = i * cellsY + j;
                }
                if (xs.get(i) <= tx && tx <= xs.get(i+1) && ys.get(j) <= ty && ty <= ys.get(j+1)) {
                    endCell = i * cellsY + j;
                }
            }
        }

        // For each wall, we need to find which adjacent cells it separates.
        // Since walls are axis-aligned and non-intersecting (except at endpoints),
        // we can process them.
        for (int[] wall : walls) {
            int x1 = wall[0], y1 = wall[1], x2 = wall[2], y2 = wall[3];
            if (y1 == y2) { // horizontal wall
                int y = y1;
                int yi = yMap.get(y);
                // The wall lies on the line between row yi-1 and yi (since y is a boundary)
                // Actually yi is the index of y in compressed list. The cells above have y-index yi-1, below have yi.
                // But careful: y is at the boundary; cells are between ys[yi-1]..ys[yi] and ys[yi]..ys[yi+1].
                // The wall at y separates cells whose y-range includes y at the top or bottom.
                // Since wall is on the line y, it separates cells that are adjacent vertically across that line.
                // The cells that touch this line from above have j = yi-1, from below have j = yi.
                // But only for x-range that the wall covers.
                int xLeft = x1, xRight = x2;
                // Find compressed x indices covering the wall's x-range
                int xiStart = xMap.get(xLeft);
                int xiEnd = xMap.get(xRight);
                // The wall spans from xs[xiStart] to xs[xiEnd].
                // For each cell column i from xiStart to xiEnd-1, the wall separates cell (i, yi-1) and (i, yi).
                // But we must ensure yi-1 >= 0 and yi < cellsY.
                if (yi > 0 && yi < cellsY) {
                    for (int i = xiStart; i < xiEnd; i++) {
                        int cellAbove = i * cellsY + (yi - 1);
                        int cellBelow = i * cellsY + yi;
                        union(cellAbove, cellBelow);
                    }
                }
            } else { // vertical wall: x1 == x2
                int x = x1;
                int xi = xMap.get(x);
                if (xi > 0 && xi < cellsX) {
                    int yBottom = y1, yTop = y2;
                    int yjStart = yMap.get(yBottom);
                    int yjEnd = yMap.get(yTop);
                    for (int j = yjStart; j < yjEnd; j++) {
                        int cellLeft = (xi - 1) * cellsY + j;
                        int cellRight = xi * cellsY + j;
                        union(cellLeft, cellRight);
                    }
                }
            }
        }

        // Now find the number of walls crossed = number of different components between start and end
        // Actually union-find merges cells that are NOT separated by any wall.
        // So the number of walls to cross is the number of distinct component boundaries we must cross.
        // But we can compute distance in terms of component changes.
        // Simpler: BFS on components, edges exist if two cells are adjacent and NOT united (i.e., a wall separates them).
        // However, we already united cells that are NOT separated by walls.
        // So we can BFS on the component graph: each component is a node, and edges between components that are adjacent across a wall.
        // But easier: we can treat the grid of components and BFS from start cell's component to end cell's component,
        // moving to neighboring cells (4-direction) but crossing a wall if the two cells are in different components.
        // Since components are already defined, BFS on cells with cost 1 if neighbor is in different component.
        // This gives the minimum number of walls crossed.

        // BFS
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        int INF = Integer.MAX_VALUE;
        int[] dist = new int[totalCells];
        Arrays.fill(dist, INF);
        Deque<Integer> dq = new ArrayDeque<>();
        dist[startCell] = 0;
        dq.add(startCell);

        while (!dq.isEmpty()) {
            int cur = dq.poll();
            int cx = cur / cellsY;
            int cy = cur % cellsY;
            for (int d = 0; d < 4; d++) {
                int nx = cx + dx[d];
                int ny = cy + dy[d];
                if (nx < 0 || nx >= cellsX || ny < 0 || ny >= cellsY) continue;
                int nxt = nx * cellsY + ny;
                int cost = (find(cur) == find(nxt)) ? 0 : 1;
                if (dist[cur] + cost < dist[nxt]) {
                    dist[nxt] = dist[cur] + cost;
                    if (cost == 0) dq.addFirst(nxt);
                    else dq.addLast(nxt);
                }
            }
        }

        System.out.println(dist[endCell]);
    }

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    }
}

