import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, cost, next;
        Edge(int to, int cost, int next) {
            this.to = to;
            this.cost = cost;
            this.next = next;
        }
    }

    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    static class Segment {
        int x1, y1, x2, y2;
        Segment(int x1, int y1, int x2, int y2) {
            this.x1 = x1; this.y1 = y1; this.x2 = x2; this.y2 = y2;
        }
    }

    static final int INF = 1 << 29;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int W = fs.nextInt();
        int H = fs.nextInt();
        int N = fs.nextInt();

        int sx = fs.nextInt();
        int sy = fs.nextInt();
        int tx = fs.nextInt();
        int ty = fs.nextInt();

        Segment[] segs = new Segment[N];
        ArrayList<Integer> xs = new ArrayList<>();
        ArrayList<Integer> ys = new ArrayList<>();

        // boundaries for compression
        xs.add(0); xs.add(W);
        ys.add(0); ys.add(H);
        xs.add(sx); xs.add(tx);
        ys.add(sy); ys.add(ty);

        for (int i = 0; i < N; i++) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            segs[i] = new Segment(x1, y1, x2, y2);

            if (x1 == x2) {
                xs.add(x1);
                ys.add(y1);
                ys.add(y2);
            } else {
                ys.add(y1);
                xs.add(x1);
                xs.add(x2);
            }
        }

        int[] xvals = compress(xs);
        int[] yvals = compress(ys);

        int xn = xvals.length;
        int yn = yvals.length;

        // blocked vertical edges: between cell (ix-1, iy) and (ix, iy)
        boolean[][] vWall = new boolean[xn][yn - 1];
        // blocked horizontal edges: between cell (ix, iy-1) and (ix, iy)
        boolean[][] hWall = new boolean[xn - 1][yn];

        // mark walls
        for (Segment s : segs) {
            if (s.x1 == s.x2) {
                int xi = lowerBound(xvals, s.x1);
                int ya = lowerBound(yvals, Math.min(s.y1, s.y2));
                int yb = lowerBound(yvals, Math.max(s.y1, s.y2));
                for (int j = ya; j < yb; j++) vWall[xi][j] = true;
            } else {
                int yi = lowerBound(yvals, s.y1);
                int xa = lowerBound(xvals, Math.min(s.x1, s.x2));
                int xb = lowerBound(xvals, Math.max(s.x1, s.x2));
                for (int i = xa; i < xb; i++) hWall[i][yi] = true;
            }
        }

        int cellsX = xn - 1;
        int cellsY = yn - 1;
        int V = cellsX * cellsY;

        int[] head = new int[V];
        Arrays.fill(head, -1);
        ArrayList<Edge> edges = new ArrayList<>();

        for (int ix = 0; ix < cellsX; ix++) {
            for (int iy = 0; iy < cellsY; iy++) {
                int id = ix * cellsY + iy;

                if (ix + 1 < cellsX) {
                    int nid = (ix + 1) * cellsY + iy;
                    int cost = vWall[ix + 1][iy] ? 1 : 0;
                    addEdge(head, edges, id, nid, cost);
                    addEdge(head, edges, nid, id, cost);
                }
                if (iy + 1 < cellsY) {
                    int nid = ix * cellsY + (iy + 1);
                    int cost = hWall[ix][iy + 1] ? 1 : 0;
                    addEdge(head, edges, id, nid, cost);
                    addEdge(head, edges, nid, id, cost);
                }
            }
        }

        int sCellX = findCell(xvals, sx);
        int sCellY = findCell(yvals, sy);
        int tCellX = findCell(xvals, tx);
        int tCellY = findCell(yvals, ty);

        int start = sCellX * cellsY + sCellY;
        int goal = tCellX * cellsY + tCellY;

        int ans = zeroOneBFS(V, head, edges, start, goal);
        System.out.println(ans);
    }

    static void addEdge(int[] head, ArrayList<Edge> edges, int u, int v, int c) {
        edges.add(new Edge(v, c, head[u]));
        head[u] = edges.size() - 1;
    }

    static int zeroOneBFS(int V, int[] head, ArrayList<Edge> edges, int s, int t) {
        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dist[s] = 0;
        dq.add(s);

        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            if (u == t) return dist[u];
            for (int ei = head[u]; ei != -1; ei = edges.get(ei).next) {
                Edge e = edges.get(ei);
                int nd = dist[u] + e.cost;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    if (e.cost == 0) dq.addFirst(e.to);
                    else dq.addLast(e.to);
                }
            }
        }
        return dist[t];
    }

    static int[] compress(ArrayList<Integer> list) {
        Collections.sort(list);
        int m = 0;
        for (int v : list) {
            if (m == 0 || list.get(m - 1) != v) {
                list.set(m++, v);
            }
        }
        int[] res = new int[m];
        for (int i = 0; i < m; i++) res[i] = list.get(i);
        return res;
    }

    static int lowerBound(int[] a, int x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] < x) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static int findCell(int[] coords, int p) {
        int idx = lowerBound(coords, p);
        if (idx < coords.length && coords[idx] == p) {
            // point lies on a wall/grid line theoretically not allowed by statement,
            // but choose left cell if possible
            return Math.max(0, idx - 1);
        }
        return idx - 1;
    }
}

