#define MAX_WALLS 1000
#define MAX_NODES (MAX_WALLS * 2 + 2)

typedef struct {
    int x1, y1, x2, y2;
} Wall;

typedef struct {
    int to, next;
} Edge;

Wall walls[MAX_WALLS];
int wall_count;
int head[MAX_NODES];
Edge edges[MAX_NODES * MAX_NODES];
int edge_count;
int dist[MAX_NODES];
int queue[MAX_NODES];
int front, rear;
int node_count;

int sx, sy, tx, ty;
int W, H;

int is_horizontal(Wall *w) {
    return w->y1 == w->y2;
}

int is_vertical(Wall *w) {
    return w->x1 == w->x2;
}

// Check if point (x,y) is on wall w (including endpoints)
int point_on_wall(Wall *w, int x, int y) {
    if (is_horizontal(w)) {
        if (y != w->y1) return 0;
        if (x >= w->x1 && x <= w->x2) return 1;
        if (x >= w->x2 && x <= w->x1) return 1;
    } else {
        if (x != w->x1) return 0;
        if (y >= w->y1 && y <= w->y2) return 1;
        if (y >= w->y2 && y <= w->y1) return 1;
    }
    return 0;
}

// Check if two walls intersect (including at endpoints)
int walls_intersect(Wall *a, Wall *b) {
    if (is_horizontal(a) && is_horizontal(b)) {
        if (a->y1 != b->y1) return 0;
        // Check x overlap
        int a_min = a->x1 < a->x2 ? a->x1 : a->x2;
        int a_max = a->x1 > a->x2 ? a->x1 : a->x2;
        int b_min = b->x1 < b->x2 ? b->x1 : b->x2;
        int b_max = b->x1 > b->x2 ? b->x1 : b->x2;
        return (a_min <= b_max && b_min <= a_max);
    }
    if (is_vertical(a) && is_vertical(b)) {
        if (a->x1 != b->x1) return 0;
        int a_min = a->y1 < a->y2 ? a->y1 : a->y2;
        int a_max = a->y1 > a->y2 ? a->y1 : a->y2;
        int b_min = b->y1 < b->y2 ? b->y1 : b->y2;
        int b_max = b->y1 > b->y2 ? b->y1 : b->y2;
        return (a_min <= b_max && b_min <= a_max);
    }
    // One horizontal, one vertical
    Wall *h, *v;
    if (is_horizontal(a)) { h = a; v = b; }
    else { h = b; v = a; }
    int vx = v->x1;
    int hy = h->y1;
    // Check if vx is within h's x range
    int hx_min = h->x1 < h->x2 ? h->x1 : h->x2;
    int hx_max = h->x1 > h->x2 ? h->x1 : h->x2;
    if (vx < hx_min || vx > hx_max) return 0;
    // Check if hy is within v's y range
    int vy_min = v->y1 < v->y2 ? v->y1 : v->y2;
    int vy_max = v->y1 > v->y2 ? v->y1 : v->y2;
    if (hy < vy_min || hy > vy_max) return 0;
    return 1;
}

// Check if a point is inside the activity area (excluding boundaries)
int inside_area(int x, int y) {
    return x > 0 && x < W && y > 0 && y < H;
}

// Check if a point is on the boundary of activity area
int on_boundary(int x, int y) {
    return x == 0 || x == W || y == 0 || y == H;
}

void add_edge(int u, int v) {
    edges[edge_count].to = v;
    edges[edge_count].next = head[u];
    head[u] = edge_count++;
}

void build_graph() {
    node_count = 2; // node 0 = start, node 1 = end
    // Each wall contributes two nodes: one for each side?
    // Actually we treat each wall as two half-edges: crossing the wall means going from one side to the other.
    // For N walls, we have 2*N nodes (one for each side of each wall), plus start and end.
    // But we need to connect nodes that are reachable without crossing walls.
    // This is complex. Instead, we'll use a simpler approach: BFS on regions.
    // Since coordinates are integers and walls are axis-aligned, we can discretize.
    // But given constraints (W,H up to 10000, N up to 1000), we can do a simple BFS on a grid?
    // No, W*H too large.
    // Another approach: treat each wall as a node in a graph, and find shortest path from start to end
    // where edge weight is 1 if you cross a wall, and you can move between walls if they are connected by a region.
    // This is essentially building a planar graph of regions.
    // Since N <= 1000, we can use a sweep line / segment tree approach, but that's complex.
    // Given this is a programming contest problem, there is likely a simpler solution.
    // Let's think: we want minimum number of walls crossed. This is equivalent to finding the minimum number of walls
    // that separate start and end. This is like a shortest path in the dual graph of the walls.
    // Since walls are axis-aligned and don't intersect (except at endpoints), we can treat each wall as an edge
    // in a planar graph, and the regions are faces. The number of regions is O(N^2) worst case, but N=1000 might be okay.
    // Actually, with axis-aligned non-intersecting walls (except at endpoints), the number of regions is O(N).
    // We can build a graph where each region is a node, and two regions are adjacent if they share a wall segment.
    // Then the answer is the number of walls on the shortest path from start's region to end's region.
    // To find which region a point belongs to, we can do a point location using a sweep line with a balanced BST.
    // This is implementable but lengthy.
    // Alternative: Since N is small (1000), we can do a BFS on the set of walls.
    // Define a graph where vertices are walls, and there is an edge between two walls if they are connected
    // (i.e., you can move from one wall to the other without crossing any wall).
    // Then the answer is the minimum number of walls you need to cross to go from start to end.
    // This can be modeled as: start and end are points. We want to find a path from start to end that crosses as few walls as possible.
    // This is equivalent to: treat each wall as having a "cost" of 1 to cross, and we can move freely in the plane.
    // Then the minimal number of walls crossed is the shortest path in a graph where nodes are the start, end, and all walls,
    // and edges exist if you can go from one to another without crossing any wall (i.e., the line segment between them doesn't cross any wall).
    // But this is not correct because you might cross a wall multiple times.
    // Actually, the minimal number of walls crossed is the minimum over all paths of the number of times you cross a wall.
    // This is equivalent to: treat each wall as an obstacle that you can cross at a cost of 1.
    // This is a classic problem: minimum number of lines crossed to go from point A to point B.
    // Since walls are axis-aligned and don't intersect, we can use a simple algorithm:
    // For each wall, check if the line segment from start to end crosses it. But that's only if you go straight.
    // The optimal path might not be straight.
    // However, for axis-aligned walls, the minimum number of walls crossed is equal to the number of walls that
    // "separate" the start and end in some sense. Actually, consider the arrangement of walls.
    // The minimum number of walls to cross is the length of the shortest path in the dual graph.
    // Since walls are axis-aligned and non-intersecting (except at endpoints), the dual graph is a grid-like graph.
    // We can build it by considering all x-coordinates (wall endpoints and start/end) and y-coordinates,
    // then creating a grid of cells. But the number of cells could be up to (2N+2)^2 = 4 million, which might be borderline but okay in C with optimization.
    // Let's check: N=1000, so 2002 x 2002 = ~4 million cells. BFS on 4 million nodes is okay (memory ~ 4M * 4 bytes = 16 MB for distances, plus graph).
    // Actually we don't need to store graph explicitly; we can do BFS on the grid.
    // So we'll discretize coordinates.
    // Steps:
    // 1. Collect all unique x coordinates from wall endpoints, start, end, and also 0 and W (boundaries).
    // 2. Collect all unique y coordinates similarly.
    // 3. Sort and map to indices.
    // 4. Create a grid of cells. Each cell is a region bounded by these coordinates.
    // 5. Mark walls on the edges between cells.
    // 6. BFS from start cell to end cell, moving up/down/left/right. Crossing a wall costs 1.
    // But we need to be careful: walls are line segments, so they occupy entire cell boundaries.
    // Since walls are axis-aligned and don't intersect except at endpoints, we can mark which edges are blocked by walls.
    // Actually, crossing a wall means moving from one cell to an adjacent cell across a boundary that contains a wall.
    // So we can precompute for each vertical boundary (between x[i] and x[i+1]) and each y interval, whether there is a wall there.
    // Similarly for horizontal boundaries.
    // Then BFS on the grid cells (x_idx from 0 to X-2, y_idx from 0 to Y-2).
    // The number of cells is at most (2N+3)*(2N+3) ~ 4 million, which is okay.
    // Memory: we need to store for each cell the distance (int), and for each boundary the presence of walls.
    // For walls, we can store as arrays of booleans: horizontal_walls[x][y] for each x between 0..X-1 and y between 0..Y-2? Actually need to map.
    // Better: use a 2D array for distances (short), and for walls, use a 2D array for vertical walls (between cells) and horizontal walls.
    // But 4M ints is 16 MB, two such arrays is 32 MB, plus walls arrays maybe another 8 MB, total < 64 MB, acceptable.
    // However, we need to be careful about stack size; use global arrays or malloc.
    // Let's implement this approach.
}

int main() {
    scanf("%d %d", &W, &H);
    scanf("%d %d %d %d", &sx, &sy, &tx, &ty);
    scanf("%d", &wall_count);
    for (int i = 0; i < wall_count; i++) {
        scanf("%d %d %d %d", &walls[i].x1, &walls[i].y1, &walls[i].x2, &walls[i].y2);
        // Ensure x1 <= x2 and y1 <= y2 for easier handling
        if (walls[i].x1 > walls[i].x2) {
            int tmp = walls[i].x1; walls[i].x1 = walls[i].x2; walls[i].x2 = tmp;
        }
        if (walls[i].y1 > walls[i].y2) {
            int tmp = walls[i].y1; walls[i].y1 = walls[i].y2; walls[i].y2 = tmp;
        }
    }

    // Collect unique x coordinates
    int xs[2005];
    int xcount = 0;
    xs[xcount++] = 0;
    xs[xcount++] = W;
    xs[xcount++] = sx;
    xs[xcount++] = tx;
    for (int i = 0; i < wall_count; i++) {
        xs[xcount++] = walls[i].x1;
        xs[xcount++] = walls[i].x2;
    }
    // Sort and unique
    for (int i = 0; i < xcount; i++) {
        for (int j = i+1; j < xcount; j++) {
            if (xs[i] > xs[j]) {
                int tmp = xs[i]; xs[i] = xs[j]; xs[j] = tmp;
            }
        }
    }
    int uniq_xcount = 0;
    for (int i = 0; i < xcount; i++) {
        if (i == 0 || xs[i] != xs[i-1]) {
            xs[uniq_xcount++] = xs[i];
        }
    }

    // Collect unique y coordinates
    int ys[2005];
    int ycount = 0;
    ys[ycount++] = 0;
    ys[ycount++] = H;
    ys[ycount++] = sy;
    ys[ycount++] = ty;
    for (int i = 0; i < wall_count; i++) {
        ys[ycount++] = walls[i].y1;
        ys[ycount++] = walls[i].y2;
    }
    for (int i = 0; i < ycount; i++) {
        for (int j = i+1; j < ycount; j++) {
            if (ys[i] > ys[j]) {
                int tmp = ys[i]; ys[i] = ys[j]; ys[j] = tmp;
            }
        }
    }
    int uniq_ycount = 0;
    for (int i = 0; i < ycount; i++) {
        if (i == 0 || ys[i] != ys[i-1]) {
            ys[uniq_ycount++] = ys[i];
        }
    }

    int X = uniq_xcount - 1; // number of cells in x direction
    int Y = uniq_ycount - 1; // number of cells in y direction

    // Map coordinates to indices
    int sx_idx = -1, sy_idx = -1, tx_idx = -1, ty_idx = -1;
    for (int i = 0; i < uniq_xcount; i++) {
        if (xs[i] == sx) sx_idx = i;
        if (xs[i] == tx) tx_idx = i;
    }
    for (int i = 0; i < uniq_ycount; i++) {
        if (ys[i] == sy) sy_idx = i;
        if (ys[i] == ty) ty_idx = i;
    }

    // Allocate distance array: dist[Y][X] (Y rows, X columns)
    int *dist = (int*)malloc(Y * X * sizeof(int));
    for (int i = 0; i < Y * X; i++) dist[i] = -1;

    // Allocate wall arrays: vertical_walls[Y][X+1] and horizontal_walls[Y+1][X]
    // vertical_walls[y][x] indicates a wall on the vertical line between cell (x-1, y) and (x, y) for x from 0 to X
    // Actually, vertical walls are at x coordinates (between xs[i] and xs[i+1]), so for each x index (0..X-1) we have vertical boundaries at left and right.
    // Let's define: vwall[y][x] = 1 if there is a vertical wall at xs[x] between ys[y] and ys[y+1] (i.e., on the left boundary of cell (x,y)).
    // Similarly, hwall[y][x] = 1 if there is a horizontal wall at ys[y] between xs[x] and xs[x+1] (i.e., on the bottom boundary of cell (x,y)).
    // Size: vwall[Y][X+1] and hwall[Y+1][X]
    int *vwall = (int*)calloc(Y * (X+1), sizeof(int));
    int *hwall = (int*)calloc((Y+1) * X, sizeof(int));

    // Mark walls
    for (int i = 0; i < wall_count; i++) {
        Wall *w = &walls[i];
        if (is_horizontal(w)) {
            int y = w->y1;
            // Find y index
            int y_idx = -1;
            for (int j = 0; j < uniq_ycount; j++) {
                if (ys[j] == y) { y_idx = j; break; }
            }
            // Find x range
            int x_left = w->x1, x_right = w->x2;
            int left_idx = -1, right_idx = -1;
            for (int j = 0; j < uniq_xcount; j++) {
                if (xs[j] == x_left) left_idx = j;
                if (xs[j] == x_right) right_idx = j;
            }
            // Mark horizontal walls on the top/bottom of cells? Since wall is at y, and cells are between ys[j] and ys[j+1].
            // The wall lies on the horizontal line at ys[y_idx]. This is the top boundary of cells at y_idx-1 (if y_idx>0) and bottom boundary of cells at y_idx (if y_idx<Y).
            // But we need to consider which cells this wall separates. Since walls are inside the area (not on boundary), y is between 0 and H.
            // We'll mark on the bottom of cells at y_idx (i.e., hwall[y_idx][x] for x from left_idx to right_idx-1).
            // Also need to ensure we don't mark outside.
            if (y_idx > 0 && y_idx < uniq_ycount) {
                for (int x = left_idx; x < right_idx; x++) {
                    if (x >= 0 && x < X) {
                        hwall[y_idx * X + x] = 1;
                    }
                }
            }
        } else { // vertical
            int x = w->x1;
            int x_idx = -1;
            for (int j = 0; j < uniq_xcount; j++) {
                if (xs[j] == x) { x_idx = j; break; }
            }
            int y_bottom = w->y1, y_top = w->y2;
            int bottom_idx = -1, top_idx = -1;
            for (int j = 0; j < uniq_ycount; j++) {
                if (ys[j] == y_bottom) bottom_idx = j;
                if (ys[j] == y_top) top_idx = j;
            }
            // Mark vertical walls on the right boundary of cells at x_idx-1? Actually at xs[x_idx], which is left boundary of cells at x_idx.
            // So mark vwall[y][x_idx] for y from bottom_idx to top_idx-1.
            if (x_idx > 0 && x_idx < uniq_xcount) {
                for (int y = bottom_idx; y < top_idx; y++) {
                    if (y >= 0 && y < Y) {
                        vwall[y * (X+1) + x_idx] = 1;
                    }
                }
            }
        }
    }

    // BFS
    int start_cell = sy_idx * X + sx_idx; // Note: sy_idx is row index, sx_idx is column index
    int end_cell = ty_idx * X + tx_idx;
    dist[start_cell] = 0;
    int *q = (int*)malloc(Y * X * sizeof(int));
    int qf = 0, qb = 0;
    q[qb++] = start_cell;

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (qf < qb) {
        int cur = q[qf++];
        int cy = cur / X;
        int cx = cur % X;
        int d = dist[cur];

        if (cur == end_cell) {
            printf("%d\n", d);
            free(dist); free(q); free(vwall); free(hwall);
            return 0;
        }

        for (int dir = 0; dir < 4; dir++) {
            int nx = cx + dx[dir];
            int ny = cy + dy[dir];
            if (nx < 0 || nx >= X || ny < 0 || ny >= Y) continue;
            // Check if crossing a wall
            int cost = 0;
            if (dx[dir] == -1) { // moving left: cross vertical wall at cx (left boundary of current cell)
                if (vwall[cy * (X+1) + cx]) cost = 1;
            } else if (dx[dir] == 1) { // moving right: cross vertical wall at cx+1 (right boundary)
                if (vwall[cy * (X+1) + (cx+1)]) cost = 1;
            } else if (dy[dir] == -1) { // moving down: cross horizontal wall at cy (bottom boundary)
                if (hwall[cy * X + cx]) cost = 1;
            } else if (dy[dir] == 1) { // moving up: cross horizontal wall at cy+1 (top boundary)
                if (hwall[(cy+1) * X + cx]) cost = 1;
            }
            int nd = d + cost;
            int nidx = ny * X + nx;
            if (dist[nidx] == -1 || nd < dist[nidx]) {
                dist[nidx] = nd;
                q[qb++] = nidx;
            }
        }
    }

    // Should not reach here
    printf("-1\n");
    free(dist); free(q); free(vwall); free(hwall);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAXN 205
#define INF 1000000

int xs[MAXN], ys[MAXN], nxs, nys;
// walls stored as segments
int wx1[MAXN], wy1[MAXN], wx2[MAXN], wy2[MAXN];
int nw;
int dist[MAXN][MAXN];
// deque BFS
int dqx[MAXN*MAXN*2], dqy[MAXN*MAXN*2];
int head, tail;

int cmp(const void*a,const void*b){return *(int*)a-*(int*)b;}

int wall_between_h(int xi, int yi) { // between cell (xi,yi) and (xi+1,yi): vertical boundary at x=xs[xi+1], y in [ys[yi],ys[yi+1]]
    int x = xs[xi+1]; int y0=ys[yi], y1=ys[yi+1];
    for(int i=0;i<nw;i++){
        if(wx1[i]==wx2[i] && wx1[i]==x){
            int a=wy1[i]<wy2[i]?wy1[i]:wy2[i], b=wy1[i]<wy2[i]?wy2[i]:wy1[i];
            if(a<=y0 && y1<=b) return 1;
        }
    }
    return 0;
}
int wall_between_v(int xi, int yi) { // between cell (xi,yi) and (xi,yi+1): horizontal boundary at y=ys[yi+1]
    int y = ys[yi+1]; int x0=xs[xi], x1=xs[xi+1];
    for(int i=0;i<nw;i++){
        if(wy1[i]==wy2[i] && wy1[i]==y){
            int a=wx1[i]<wx2[i]?wx1[i]:wx2[i], b=wx1[i]<wx2[i]?wx2[i]:wx1[i];
            if(a<=x0 && x1<=b) return 1;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x1, y1, x2, y2;
} Seg;

typedef struct {
    ll v;
    int type; /* 0: from point, 1: from segment endpoint */
} Key;

typedef struct {
    int to, w, next;
} Edge;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a, y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int cmp_key(const void *a, const void *b) {
    const Key *x = (const Key*)a;
    const Key *y = (const Key*)b;
    if (x->v < y->v) return -1;
    if (x->v > y->v) return 1;
    if (x->type < y->type) return -1;
    if (x->type > y->type) return 1;
    return 0;
}

static int lower_bound_ll(ll *arr, int n, ll v) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] < v) l = m + 1;
        else r = m;
    }
    return l;
}

static int lower_bound_key(Key *arr, int n, ll v, int type) {
    Key k;
    k.v = v;
    k.type = type;
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m].v < k.v || (arr[m].v == k.v && arr[m].type < k.type)) l = m + 1;
        else r = m;
    }
    return l;
}

static void add_edge(Edge *edges, int *head, int *ecnt, int u, int v, int w) {
    edges[*ecnt].to = v;
    edges[*ecnt].w = w;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

int main(void) {
    ll W, H;
    int N;
    if (scanf("%lld %lld %d", &W, &H, &N) != 3) return 0;

    Seg *vert = (Seg*)malloc(sizeof(Seg) * N);
    Seg *hori = (Seg*)malloc(sizeof(Seg) * N);
    int nv = 0, nh = 0;

    ll sx, sy, tx, ty;

    /* Problem statement format is not explicitly shown in prompt,
       assume next line is start/end, then N wall lines:
       x1 y1 x2 y2
       axis-parallel segments only.
    */
    scanf("%lld %lld %lld %lld", &sx, &sy, &tx, &ty);

    for (int i = 0; i < N; i++) {
        ll x1, y1, x2, y2;
        scanf("%lld %lld %lld %lld", &x1, &y1, &x2, &y2);
        if (x1 == x2) {
            if (y1 > y2) { ll t = y1; y1 = y2; y2 = t; }
            vert[nv++] = (Seg){x1, y1, x2, y2};
        } else {
            if (x1 > x2) { ll t = x1; x1 = x2; x2 = t; }
            hori[nh++] = (Seg){x1, y1, x2, y2};
        }
    }

    /* Coordinate compression of open cells:
       x-keys: points use type 0, wall-x endpoints use type 1.
       This ensures walls lie on boundaries between cell columns.
       Same for y.
    */
    Key *xk = (Key*)malloc(sizeof(Key) * (2 * nv + 2));
    Key *yk = (Key*)malloc(sizeof(Key) * (2 * nh + 2));
    int xkn = 0, ykn = 0;

    xk[xkn++] = (Key){sx, 0};
    xk[xkn++] = (Key){tx, 0};
    for (int i = 0; i < nv; i++) xk[xkn++] = (Key){vert[i].x1, 1};

    yk[ykn++] = (Key){sy, 0};
    yk[ykn++] = (Key){ty, 0};
    for (int i = 0; i < nh; i++) yk[ykn++] = (Key){hori[i].y1, 1};

    qsort(xk, xkn, sizeof(Key), cmp_key);
    qsort(yk, ykn, sizeof(Key), cmp_key);

    int xn = 0, yn = 0;
    for (int i = 0; i < xkn; i++) {
        if (i == 0 || xk[i].v != xk[i-1].v || xk[i].type != xk[i-1].type)
            xk[xn++] = xk[i];
    }
    for (int i = 0; i < ykn; i++) {
        if (i == 0 || yk[i].v != yk[i-1].v || yk[i].type != yk[i-1].type)
            yk[yn++] = yk[i];
    }

    int C = xn - 1; /* columns */
    int R = yn - 1; /* rows */

    if (C <= 0 || R <= 0) {
        printf("0\n");
        free(vert); free(hori); free(xk); free(yk);
        return 0;
    }

    int cells = C * R;

    /* blocked crossing costs between adjacent cells:
       moving horizontally across vertical boundary bx (between col bx-1 and bx):
       vb[bx][r] = 1 if vertical wall exists there over row r
       bx in [1..C-1]
       moving vertically across horizontal boundary by (between row by-1 and by):
       hb[by][c] = 1 if horizontal wall exists there over col c
       by in [1..R-1]
    */
    unsigned char *vb = (unsigned char*)calloc((size_t)(C + 1) * R, 1);
    unsigned char *hb = (unsigned char*)calloc((size_t)(R + 1) * C, 1);

    for (int i = 0; i < nv; i++) {
        int bx = lower_bound_key(xk, xn, vert[i].x1, 1);
        int y1i = lower_bound_key(yk, yn, vert[i].y1, 0);
        int y2i = lower_bound_key(yk, yn, vert[i].y2, 0);
        for (int r = y1i; r < y2i; r++) {
            vb[(size_t)bx * R + r] = 1;
        }
    }

    for (int i = 0; i < nh; i++) {
        int by = lower_bound_key(yk, yn, hori[i].y1, 1);
        int x1i = lower_bound_key(xk, xn, hori[i].x1, 0);
        int x2i = lower_bound_key(xk, xn, hori[i].x2, 0);
        for (int c = x1i; c < x2i; c++) {
            hb[(size_t)by * C + c] = 1;
        }
    }

    int sxc = lower_bound_key(xk, xn, sx, 0);
    int syc = lower_bound_key(yk, yn, sy, 0);
    int txc = lower_bound_key(xk, xn, tx, 0);
    int tyc = lower_bound_key(yk, yn, ty, 0);

    int s = syc * C + sxc;
    int t = tyc * C + txc;

    /* 0-1 BFS */
    int maxEdges = cells * 4 + 5;
    Edge *edges = (Edge*)malloc(sizeof(Edge) * maxEdges);
    int *head = (int*)malloc(sizeof(int) * cells);
    for (int i = 0; i < cells; i++) head[i] = -1;
    int ecnt = 0;

    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            int u = r * C + c;
            if (c + 1 < C) {
                int v = r * C + (c + 1);
                int w = vb[(size_t)(c + 1) * R + r] ? 1 : 0;
                add_edge(edges, head, &ecnt, u, v, w);
                add_edge(edges, head, &ecnt, v, u, w);
            }
            if (r + 1 < R) {
                int v = (r + 1) * C + c;
                int w = hb[(size_t)(r + 1) * C + c] ? 1 : 0;
                add_edge(edges, head, &ecnt, u, v, w);
                add_edge(edges, head, &ecnt, v, u, w);
            }
        }
    }

    const int INF = 1e9;
    int *dist = (int*)malloc(sizeof(int) * cells);
    for (int i = 0; i < cells; i++) dist[i] = INF;

    int *deq = (int*)malloc(sizeof(int) * (cells * 2 + 5));
    int front = cells, back = cells;
    dist[s] = 0;
    deq[back++] = s;

    while (front < back) {
        int u = deq[front++];
        if (u == t) break;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int nd = dist[u] + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                if (edges[e].w == 0) deq[--front] = v;
                else deq[back++] = v;
            }
        }
    }

    printf("%d\n", dist[t]);

    free(vert);
    free(hori);
    free(xk);
    free(yk);
    free(vb);
    free(hb);
    free(edges);
    free(head);
    free(dist);
    free(deq);
    return 0;
}

import sys
from collections import deque

def main():
    input = sys.stdin.readline
    W, H = map(int, input().split())
    xs, ys, xt, yt = map(int, input().split())
    N = int(input())

    vertical = []
    horizontal = []

    xvals = [0, W, xs, xt]
    yvals = [0, H, ys, yt]

    for _ in range(N):
        x1, y1, x2, y2 = map(int, input().split())
        if x1 == x2:
            if y1 > y2:
                y1, y2 = y2, y1
            vertical.append((x1, y1, y2))
            xvals.append(x1)
            yvals.append(y1)
            yvals.append(y2)
        else:
            if x1 > x2:
                x1, x2 = x2, x1
            horizontal.append((y1, x1, x2))
            yvals.append(y1)
            xvals.append(x1)
            xvals.append(x2)

    # Coordinate compression with gaps preserved.
    xuniq = sorted(set(xvals))
    yuniq = sorted(set(yvals))

    xmap = {}
    cx = 0
    prev = None
    for v in xuniq:
        if prev is None:
            xmap[v] = cx
        else:
            if v - prev >= 2:
                cx += 2
            else:
                cx += 1
            xmap[v] = cx
        prev = v
    X = cx + 1

    ymap = {}
    cy = 0
    prev = None
    for v in yuniq:
        if prev is None:
            ymap[v] = cy
        else:
            if v - prev >= 2:
                cy += 2
            else:
                cy += 1
            ymap[v] = cy
        prev = v
    Y = cy + 1

    # blocked vertical edges: between (x-1,y) <-> (x,y)
    vblock = [[False] * Y for _ in range(X)]
    # blocked horizontal edges: between (x,y-1) <-> (x,y)
    hblock = [[False] * Y for _ in range(X)]

    for x, y1, y2 in vertical:
        xi = xmap[x]
        y1i = ymap[y1]
        y2i = ymap[y2]
        for y in range(y1i + 1, y2i):
            vblock[xi][y] = True

    for y, x1, x2 in horizontal:
        yi = ymap[y]
        x1i = xmap[x1]
        x2i = xmap[x2]
        for x in range(x1i + 1, x2i):
            hblock[x][yi] = True

    # Cells are open regions between compressed lines.
    # Start/end points are guaranteed not on walls/boundary, so they lie in cells:
    sx = xmap[xs]
    sy = ymap[ys]
    tx = xmap[xt]
    ty = ymap[yt]

    dist = [[10**18] * (Y - 1) for _ in range(X - 1)]
    dq = deque()
    dist[sx][sy] = 0
    dq.append((sx, sy))

    while dq:
        x, y = dq.popleft()
        d = dist[x][y]
        if x == tx and y == ty:
            break

        # left
        if x > 0:
            nd = d + (1 if vblock[x][y] else 0)
            if nd < dist[x - 1][y]:
                dist[x - 1][y] = nd
                if vblock[x][y]:
                    dq.append((x - 1, y))
                else:
                    dq.appendleft((x - 1, y))
        # right
        if x + 1 < X - 1:
            nd = d + (1 if vblock[x + 1][y] else 0)
            if nd < dist[x + 1][y]:
                dist[x + 1][y] = nd
                if vblock[x + 1][y]:
                    dq.append((x + 1, y))
                else:
                    dq.appendleft((x + 1, y))
        # down
        if y > 0:
            nd = d + (1 if hblock[x][y] else 0)
            if nd < dist[x][y - 1]:
                dist[x][y - 1] = nd
                if hblock[x][y]:
                    dq.append((x, y - 1))
                else:
                    dq.appendleft((x, y - 1))
        # up
        if y + 1 < Y - 1:
            nd = d + (1 if hblock[x][y + 1] else 0)
            if nd < dist[x][y + 1]:
                dist[x][y + 1] = nd
                if hblock[x][y + 1]:
                    dq.append((x, y + 1))
                else:
                    dq.appendleft((x, y + 1))

    print(dist[tx][ty])

if __name__ == "__main__":
    main()
